// Differential checks of MutualUnreachMarker.js against Lean, generated by leanscript --check
import * as M from "./MutualUnreachMarker.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("f1(0n)", () => M.f1(0n), "true", false);
check("f1(1n)", () => M.f1(1n), "false", false);
check("f1(2n)", () => M.f1(2n), "true", false);
check("f1(5n)", () => M.f1(5n), "false", false);
check("f1(13n)", () => M.f1(13n), "false", false);
check("f2(0n)", () => M.f2(0n), "7", false);
check("f2(1n)", () => M.f2(1n), "0", false);
check("f2(2n)", () => M.f2(2n), "1", false);
check("f2(5n)", () => M.f2(5n), "0", false);
check("f2(13n)", () => M.f2(13n), "0", false);

console.log(`MutualUnreachMarker.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
